// Actual Service flows in isolated synthetic storage. Supabase is blocked.
const fs=require('node:fs'),path=require('node:path');
const {chromium,webkit}=require('playwright'),seed=require('./ui-fixture.cjs');
const url=process.env.PREVIEW_URL,output=path.join(process.env.AUDIT_OUTPUT||'responsive-audit-output','service-modals');
if(!url)throw Error('PREVIEW_URL required');fs.mkdirSync(output,{recursive:true});
const matrix={},evidence={},screenshots=[],errors=[],isolationErrors=[];
const check=(key,ok,data)=>{matrix[key]=ok?'PASS':'FAIL';if(data!==undefined)evidence[key]=data;console.log(key+' '+matrix[key]);};
async function run(browser,engine,device,width,height){
 const prefix=engine+'.'+device,dir=path.join(output,prefix);fs.mkdirSync(dir,{recursive:true});let context,page,mutated=false;
 async function fresh(){await context?.close();context=await browser.newContext({viewport:{width,height},deviceScaleFactor:1,hasTouch:true,locale:'de-CH',timezoneId:'Europe/Zurich'});await context.addInitScript(seed);await context.route('**/*',r=>/supabase/i.test(r.request().url())||new URL(r.request().url()).hostname==='vercel.live'?r.abort():r.continue());page=await context.newPage();page.setDefaultTimeout(10000);page.on('pageerror',e=>{const item={engine,device,message:e.message};if(/supabase\.co/.test(e.message)&&/access control checks/.test(e.message))isolationErrors.push(item);else errors.push(item);});mutated=false;await page.goto(url,{waitUntil:'domcontentloaded'});await page.locator('.role-selection [data-role="service"]').click();await page.locator('.app-shell').waitFor();await page.locator('.service-entry-transition').waitFor({state:'detached'});}
 async function shot(state,metrics){const file=path.join(dir,state+'.png');await page.screenshot({path:file,animations:'disabled'});const viewport=await page.evaluate(()=>({width:innerWidth,height:innerHeight,scrollWidth:document.documentElement.scrollWidth}));check(prefix+'.overflow.'+state,viewport.scrollWidth<=viewport.width,viewport);screenshots.push({file,engine,device,state,requestedViewport:[viewport.width,viewport.height],referenceViewport:[width,height],metrics,syntheticLocalMutation:mutated,realDataMutation:false});}
 async function measure(sel){return page.locator(sel).evaluate(modal=>{
  const rect=e=>e?.getBoundingClientRect().toJSON(),body=modal.querySelector(':scope > .modal-body,:scope > .service-success-body'),head=modal.querySelector(':scope > .modal-head,:scope > .service-success-head'),footer=modal.querySelector(':scope > .modal-actions,:scope > .service-success-footer'),layer=modal.parentElement,header=document.querySelector('.topbar'),m=rect(modal),h=rect(header),close=modal.querySelector('.close-button'),b=rect(close),last=body?.lastElementChild;
  const centerHit=e=>{const r=rect(e);return e.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2));};
  const backgroundHit=document.elementFromPoint(h.x+h.width/2,h.y+h.height/2);
  return{modal:m,topGap:m.top,serviceHeader:h,headerInBackgroundVisible:h.height>0&&h.top>=0&&h.bottom<=m.top&&getComputedStyle(header).visibility==='visible',backgroundInert:header.inert,backgroundHitIsOverlay:backgroundHit===layer,overlayBackground:getComputedStyle(layer).backgroundColor,overlayBlur:getComputedStyle(layer).backdropFilter,modalHeader:rect(head),body:rect(body),footer:rect(footer),footerHeight:footer?.getBoundingClientRect().height,bodyScrollHeight:body?.scrollHeight,bodyClientHeight:body?.clientHeight,bodyScrollTop:body?.scrollTop,lastBodyChild:rect(last),containerScrollTop:modal.scrollTop,layerScrollTop:layer.scrollTop,radii:[getComputedStyle(modal).borderTopLeftRadius,getComputedStyle(modal).borderTopRightRadius,getComputedStyle(modal).borderBottomLeftRadius,getComputedStyle(modal).borderBottomRightRadius],buttons:[...footer.querySelectorAll('button')].map(e=>({box:rect(e),hit:centerHit(e)})),close:close?{box:b,hit:centerHit(close)}:null,scrollAreas:[layer,modal,body,...body.querySelectorAll('*')].filter(e=>e.scrollHeight>e.clientHeight+1&&/(auto|scroll)/.test(getComputedStyle(e).overflowY)).map(e=>e.className),viewport:[innerWidth,innerHeight]};
 });}
 async function geometry(name,sel){await page.waitForFunction(()=>document.querySelector('.topbar')?.inert);const m=await measure(sel);check(prefix+'.'+name+'.header-visible',m.headerInBackgroundVisible&&m.backgroundInert&&m.backgroundHitIsOverlay,m);check(prefix+'.'+name+'.bounds',m.modal.top>=80&&m.modal.left>=10&&m.modal.right<=width-10&&m.modal.bottom<=height-11&&m.radii.every(x=>x==='16px'));check(prefix+'.'+name+'.separate-scroll-footer',m.body.top>=m.modalHeader.bottom-1&&m.body.bottom<=m.footer.top+1&&m.footer.bottom<=m.modal.bottom&&m.containerScrollTop===0&&m.layerScrollTop===0&&m.scrollAreas.every(x=>/modal-body|service-success-body/.test(x)));check(prefix+'.'+name+'.footer-interactive',m.buttons.every(b=>b.hit));if(m.buttons.length===2)check(prefix+'.'+name+'.footer-50-50',Math.abs(m.buttons[0].box.width-m.buttons[1].box.width)<1&&Math.abs(m.buttons[0].box.height-m.buttons[1].box.height)<1);if(m.close)check(prefix+'.'+name+'.close-reachable',m.close.hit&&m.close.box.top>=m.modal.top&&m.close.box.bottom<=m.modal.bottom);return m;}
 async function scrollCheck(name,sel,top){await page.locator(sel+' > .modal-body').evaluate(e=>e.scrollTop=e.scrollHeight);const bottom=await measure(sel);check(prefix+'.'+name+'.body-scroll-footer-fixed',bottom.bodyScrollTop>0&&Math.abs(bottom.footer.top-top.footer.top)<1&&Math.abs(bottom.modalHeader.top-top.modalHeader.top)<1&&bottom.lastBodyChild.bottom<=bottom.footer.top+1&&bottom.containerScrollTop===0&&bottom.layerScrollTop===0,bottom);return bottom;}
 async function section(name,fn){try{await fn();}catch(e){check(prefix+'.'+name,false,{error:String(e)});await shot('FAIL-'+name).catch(()=>{});}}
 try{
  await section('checkin',async()=>{await fresh();await shot('01-service-main');await page.getByRole('button',{name:'Zimmer 21 öffnen'}).click();const top=await geometry('checkin','.checkin-choice-modal');await shot('02-checkin-open',top);
   const cols=await page.locator('.checkin-choice-body').evaluate(e=>({count:e.querySelector('.checkin-count-block').getBoundingClientRect().toJSON(),table:e.querySelector('.table-picker').getBoundingClientRect().toJSON(),tables:e.querySelectorAll('.table-picker button').length}));check(prefix+'.checkin.original-layout',cols.tables===50&&(device==='ipad'?cols.table.x>cols.count.right:cols.table.top>cols.count.bottom),cols);
   if(device==='iphone')await shot('03-checkin-table-footer',await scrollCheck('checkin','.checkin-choice-modal',top));
   await page.locator('.checkin-choice-modal .close-button').click();await page.locator('.checkin-choice-modal').waitFor({state:'detached'});await page.waitForFunction(()=>!document.querySelector('.topbar').inert);check(prefix+'.checkin.closed-background-restored',await page.getByRole('button',{name:'Menü öffnen'}).isVisible());
  });
  await section('special',async()=>{await fresh();await page.getByRole('button',{name:'Menü öffnen'}).click();await page.locator('[data-menu-action="special-guests"]').click();const top=await geometry('special','.special-guest-modal');await shot('04-special-open',top);
   await page.locator('[data-special-type="opera"]').click();await page.locator('[data-special-type="external"]').click();const types=await page.locator('.special-type-picker > button').evaluateAll(es=>es.map(e=>({box:e.getBoundingClientRect().toJSON(),selected:e.classList.contains('selected')})));check(prefix+'.special.opera-external-symmetric',types.length===2&&types[0].box.width===types[1].box.width&&types[0].box.height===types[1].box.height&&!types[0].selected&&types[1].selected,types);
   if(device==='iphone')await shot('05-special-table-footer',await scrollCheck('special','.special-guest-modal',top));
   await page.locator('.special-guest-modal .close-button').click();await page.waitForFunction(()=>!document.querySelector('.topbar').inert);check(prefix+'.special.close-restores-background',await page.getByRole('button',{name:'Menü öffnen'}).isVisible());
  });
  await section('success',async()=>{await fresh();await page.getByRole('button',{name:'Zimmer 21 öffnen'}).click();await page.locator('.table-picker').getByRole('button',{name:'17',exact:true}).click();await page.locator('.table-picker button.selected').filter({hasText:/^17$/}).waitFor();await page.locator('.checkin-choice-modal .modal-actions .primary').filter({hasText:'17'}).click();mutated=true;await page.locator('.service-success-body').waitFor();const m=await geometry('success','.checkin-card');await shot('06-success-with-remark',m);check(prefix+'.success.compact-height',m.modal.height<height-104);
   const note=await page.locator('.checkin-card .important-note').evaluate(e=>({heading:e.querySelector('strong').textContent,text:e.querySelector('p').textContent,color:getComputedStyle(e).backgroundColor,icon:[...e.querySelectorAll('svg')].some(s=>s.getBoundingClientRect().height>0)}));check(prefix+'.success.quiet-remark',note.heading==='Bemerkung'&&note.text==='Synthetische Bemerkung für die UI-Abnahme.'&&note.color==='rgba(0, 0, 0, 0)'&&!note.icon,note);
   const room=await page.evaluate(()=>JSON.parse(localStorage.getItem('ambassador-breakfast-rooms')).rooms.find(r=>r.room===21));check(prefix+'.success.existing-checkin-result',room.arrivedCount===2&&room.table==='Tisch 17',{arrivedCount:room.arrivedCount,table:room.table,people:room.people});
   await page.getByRole('button',{name:'Verstanden',exact:true}).click();await page.locator('.checkin-card').waitFor({state:'detached'});await page.waitForFunction(()=>!document.querySelector('.topbar').inert);check(prefix+'.success.confirmation-handler',await page.getByRole('button',{name:'Menü öffnen'}).isVisible());
  });
  if(device==='iphone')await section('editor-and-remark',async()=>{await fresh();await page.getByRole('button',{name:'Gäste bearbeiten',exact:true}).click();await page.getByRole('button',{name:'Zimmer 22 öffnen'}).click();await page.locator('.guest-edit-modal').waitFor();
   const editor=()=>page.locator('.guest-edit-modal').evaluate(e=>{const r=x=>x.getBoundingClientRect().toJSON(),b=e.querySelector('.modal-body');return{modal:r(e),header:r(e.querySelector('.modal-head')),label:r(e.querySelector('.guest-edit-grid label > span')),body:r(b),footer:r(e.querySelector('.modal-actions')),last:r(e.querySelector('.remark-edit-open')),buttons:[...e.querySelectorAll('.modal-actions button')].map(r),scrollHeight:b.scrollHeight,clientHeight:b.clientHeight};});
   const a=await editor();check(prefix+'.editor.fullscreen-first-label',a.modal.left===0&&a.modal.top<=8&&a.modal.width===width&&a.modal.bottom===height&&a.label.top>=a.header.bottom+12,a);await shot('07-editor-top',a);await page.locator('.guest-edit-modal .modal-body').evaluate(e=>e.scrollTop=e.scrollHeight);const b=await editor();check(prefix+'.editor.footer-preserved',b.body.bottom<=b.footer.top+1&&b.last.bottom<=b.footer.top&&Math.abs(b.buttons[0].width-b.buttons[1].width)<1,b);await shot('07-editor-bottom',b);
   await page.locator('.remark-edit-open').click();await page.locator('.remark-popup-modal').waitFor();const remark=()=>page.locator('.remark-popup-modal').evaluate(e=>{const r=x=>x.getBoundingClientRect().toJSON();return{modal:r(e),field:r(e.querySelector('textarea')),footer:r(e.querySelector('.remark-popup-actions')),close:r(e.querySelector('button[aria-label="Schließen"]')),viewport:[innerWidth,innerHeight]};});const normal=await remark();check(prefix+'.remark.compact',normal.modal.height<height/2&&normal.modal.top>80,normal);await shot('08-remark-normal',normal);
   await page.setViewportSize({width,height:500});await page.locator('.remark-popup-modal textarea').focus();const short=await remark();check(prefix+'.remark.reduced-viewport',short.modal.top>=0&&short.footer.bottom<=500&&short.field.bottom<=short.footer.top&&short.close.top>=0,short);await shot('08-remark-focused-short-viewport',short);
  });
 }finally{await context?.close();}
}
(async()=>{for(const engine of (process.env.MODAL_ENGINES||'chromium,webkit').split(',')){let browser;try{const local=engine==='chromium'&&process.env.LOCAL_CHROMIUM;browser=await({chromium,webkit}[engine]).launch(local?{executablePath:process.env.LOCAL_CHROMIUM,args:require(process.env.LOCAL_CHROMIUM_PACKAGE).default.args.filter(a=>a!=='--single-process')}:{headless:true});for(const[device,w,h]of[['iphone',390,844],['ipad',1024,1366]])await run(browser,engine,device,w,h);}catch(e){check(engine+'.runner',false,String(e));}finally{await browser?.close();}}
check('runtime-errors',errors.length===0,errors);fs.writeFileSync(path.join(output,'results.json'),JSON.stringify({commit:process.env.SOURCE_SHA,url,matrix,evidence,screenshots,errors,isolationErrors,conditions:{realDeviceRetest:false,realKeyboardTest:false,supabaseWrites:false,productionWrites:false,syntheticCheckins:true}},null,2));console.log(JSON.stringify({pass:Object.values(matrix).filter(v=>v==='PASS').length,fail:Object.values(matrix).filter(v=>v==='FAIL').length,screenshots:screenshots.length}));if(Object.values(matrix).includes('FAIL'))process.exitCode=1;})();
